const tasks = $input.all().map(item => item.json);

// Get today's date in Bangladesh
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Dhaka',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Find pending or in-progress tasks
// that are due today or overdue
const pendingTasks = tasks.filter(task => {
  const status = String(task.status || '').toLowerCase().trim();
  const dueDate = String(task.due_date || '').trim();

  return (
    ['pending', 'in progress'].includes(status) &&
    /^\d{4}-\d{2}-\d{2}$/.test(dueDate) &&
    dueDate <= today
  );
});

// Prepare Telegram message
let message = `📅 DAILY TASK REMINDER\n`;
message += `━━━━━━━━━━━━━━━━━━\n`;
message += `📆 Date: ${today}\n\n`;

if (pendingTasks.length === 0) {
  message += `🎉 Great! No pending or overdue tasks for today.\n`;
} else {
  message += `You have ${pendingTasks.length} task(s) to complete:\n\n`;

  pendingTasks.forEach((task, index) => {
    const overdue = task.due_date < today;

    message += `${index + 1}. ${task.task_name}\n`;
    message += `   🎯 Priority: ${task.priority || 'Normal'}\n`;
    message += `   📌 Status: ${task.status}\n`;
    message += overdue
      ? `   ⚠️ OVERDUE: ${task.due_date}\n\n`
      : `   📅 Due: ${task.due_date}\n\n`;
  });
}

message += `━━━━━━━━━━━━━━━━━━\n`;
message += `💪 Stay focused and complete your tasks!`;

return [
  {
    json: {
      message,
      task_count: pendingTasks.length,
      date: today
    }
  }
];
